<?php
$tokens = $tokens ?? [];
$newToken = $newToken ?? null;
$error = $error ?? null;
$csrf = htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8');
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>API | CampoSur</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><?php require dirname(__DIR__) . '/Views/partials/module-navigation.php'; ?><section class="module-content"><header class="admin-header"><div><p class="eyebrow">Integraciones</p><h1>Tokens API</h1><p class="setup-copy">Administra credenciales para integraciones futuras.</p></div><a class="secondary-link" href="./">Volver al dashboard</a></header><?php if ($error): ?><div class="setup-error"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><?php if ($newToken): ?><div class="setup-success"><strong>Token generado una sola vez:</strong><code><?= htmlspecialchars($newToken, ENT_QUOTES, 'UTF-8') ?></code></div><?php endif; ?><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Nuevo token</h2></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="create"><label>Nombre<input name="name" required maxlength="100"></label><label>Expira el<input type="datetime-local" name="expires_at"></label><button class="primary-button" type="submit">Generar token</button></form></article><article class="admin-panel"><header class="panel-header"><h2>Tokens emitidos</h2></header><div class="table-scroll"><table class="data-table"><thead><tr><th>Nombre</th><th>Creado</th><th>Último uso</th><th>Expiración</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach ($tokens as $token): ?><tr><td><?= htmlspecialchars($token['name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($token['created_at'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($token['last_used_at'] ?: '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($token['expires_at'] ?: '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= $token['revoked_at'] ? 'Revocado' : 'Activo' ?></td><td><?php if (!$token['revoked_at']): ?><form method="post"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="revoke"><input type="hidden" name="token_id" value="<?= (int) $token['id'] ?>"><button class="button-link" type="submit">Revocar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></article></section></section></main></body></html>
